'use strict';
const CONFIG={whatsappNumber:'919852248522',instagramUrl:'https://www.instagram.com/carnivalstudios/'};
const menu=document.querySelector('.menu');
const navigation=document.getElementById('navigation');
const closeMenu=()=>{navigation.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')};
menu.addEventListener('click',()=>{const open=navigation.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
navigation.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){closeMenu();menu.focus()}});
const photos=[{src:'/assets/wedding.webp',title:'Together, in celebration',category:'Weddings',alt:'A bride and groom during their wedding ceremony, photographed by Carnival Studios'},{src:'/assets/bride.webp',title:'A moment of their own',category:'Weddings',alt:'A couple together under warm reception lights, photographed by Carnival Studios'},{src:'/assets/prewedding.webp',title:'Just the two of you',category:'Pre-weddings',alt:'A couple with colorful parrots during an outdoor pre-wedding shoot by Carnival Studios'}];
const grid=document.getElementById('portfolio-grid');
if(grid){
 let visible=photos.slice(),current=0,trigger=null;
 const dialog=document.getElementById('lightbox');
 const showImage=()=>{const p=visible[current];document.getElementById('lightbox-image').src=p.src;document.getElementById('lightbox-image').alt=p.alt;document.getElementById('lightbox-title').textContent=p.title+' · '+(current+1)+' / '+visible.length;document.getElementById('previous-image').disabled=visible.length<2;document.getElementById('next-image').disabled=visible.length<2};
 const render=category=>{visible=category==='All'?photos.slice():photos.filter(p=>p.category===category);grid.replaceChildren();visible.forEach((p,index)=>{const button=document.createElement('button');button.className='portfolio-item';button.setAttribute('aria-label','View '+p.title+' — Carnival Studios');const wrap=document.createElement('div');wrap.className='image-wrap';const img=document.createElement('img');img.src=p.src;img.alt=p.alt;img.loading='lazy';if(p.category==='Pre-weddings')img.style.objectPosition='50% 75%';img.width=1200;img.height=1000;const action=document.createElement('span');action.className='image-action';action.textContent='↗';action.setAttribute('aria-hidden','true');wrap.append(img,action);const caption=document.createElement('div');caption.className='card-caption';const title=document.createElement('h3');title.textContent=p.title;const label=document.createElement('span');label.textContent=p.category.toUpperCase();caption.append(title,label);button.append(wrap,caption);button.addEventListener('click',()=>{current=index;trigger=button;showImage();dialog.showModal();document.getElementById('close-lightbox').focus()});grid.append(button)});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===category)));document.getElementById('result-count').textContent=visible.length+' photograph'+(visible.length===1?'':'s');document.getElementById('empty-state').hidden=visible.length!==0};
 document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>render(b.dataset.filter)));
 const initial=new URLSearchParams(location.search).get('category');render(['Weddings','Pre-weddings'].includes(initial)?initial:'All');
 document.getElementById('close-lightbox').addEventListener('click',()=>dialog.close());
 document.getElementById('previous-image').addEventListener('click',()=>{current=(current-1+visible.length)%visible.length;showImage()});
 document.getElementById('next-image').addEventListener('click',()=>{current=(current+1)%visible.length;showImage()});
 dialog.addEventListener('close',()=>trigger?.focus());
 dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
 dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){current=(current+1)%visible.length;showImage()}if(e.key==='ArrowLeft'){current=(current-1+visible.length)%visible.length;showImage()}});
}
const form=document.getElementById('enquiry-form');
if(form){
 document.body.classList.add('contact-page');
 const dateInput=document.getElementById('date');const today=new Date();const todayString=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');dateInput.min=todayString;
 const prefill=new URLSearchParams(location.search).get('service');const select=document.getElementById('service');if([...select.options].some(o=>o.value===prefill))select.value=prefill;if(prefill==='Pre-wedding')document.getElementById('event').value='Pre-wedding';
 const whatsapp=document.getElementById('whatsapp-link');const validNumber=/^[1-9]\d{7,14}$/.test(CONFIG.whatsappNumber);
 const updateLink=()=>{whatsapp.href='https://wa.me/'+CONFIG.whatsappNumber+'?text='+encodeURIComponent(document.getElementById('draft').value)};
 document.getElementById('draft').addEventListener('input',()=>{if(validNumber)updateLink()});
 if(validNumber){form.querySelector('[type=submit]').firstChild.textContent='Review your enquiry ';document.querySelector('.contact-note p').textContent='Review your enquiry, then send it in WhatsApp. The studio can discuss availability, coverage and a quote for your celebration.';}
 form.addEventListener('submit',e=>{e.preventDefault();let first=null;const fields=['name','event','date','venue','service','message'];const values={};fields.forEach(id=>{const el=document.getElementById(id);values[id]=el.value.trim();let error='';if(el.required&&!values[id])error='Please '+(el.tagName==='SELECT'?'choose an option.':'complete this field.');else if((id==='name'||id==='venue')&&values[id].length<2)error='Please enter at least 2 characters.';else if(id==='name'&&values[id].length>80)error='Keep your name under 80 characters.';else if(id==='venue'&&values[id].length>160)error='Keep the venue under 160 characters.';else if(id==='message'&&values[id].length>1000)error='Keep your message under 1,000 characters.';else if(id==='date'&&el.validity.badInput)error='Please enter a valid date.';else if(id==='date'&&values[id]&&(!/^\d{4}-\d{2}-\d{2}$/.test(values[id])||values[id]<todayString))error='Please choose today or a future date, or leave this blank.';document.getElementById(id+'-error').textContent=error;el.setAttribute('aria-invalid',String(!!error));if(error&&!first)first=el});if(first){first.focus();document.getElementById('draft-section').hidden=true;return}const lines=['Hi Carnival Studios! I’d like to enquire about an event.','','Name: '+values.name,'Event: '+values.event,'Date: '+(values.date||'Not decided'),'City/venue: '+values.venue,'Service: '+select.options[select.selectedIndex].text];if(values.message)lines.push('Details: '+values.message);lines.push('','Please let me know about availability and next steps.');document.getElementById('draft').value=lines.join('\n');document.getElementById('draft-section').hidden=false;document.getElementById('copy-status').textContent='';if(validNumber){whatsapp.hidden=false;updateLink();document.getElementById('contact-status').textContent='Your message will open in WhatsApp. Send it there to contact the studio. If WhatsApp does not open, copy the message and try again.'}document.getElementById('draft-title').focus();document.getElementById('draft-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})});
 document.getElementById('copy-message').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.getElementById('draft').value);document.getElementById('copy-status').textContent='Message copied. Paste and send it in WhatsApp to contact the studio.'}catch{const d=document.getElementById('draft');d.focus();d.select();document.getElementById('copy-status').textContent='Automatic copying is unavailable. Your message is selected; use your device’s Copy action.'}});
}
